const out = [];
const used = new Set();
const add = (category, group, topic, frame, text, sensitive) => {
  if (used.has(text)) return false;
  used.add(text);
  out.push({ id: `t3-${String(out.length + 1).padStart(5, '0')}`, category, group, topic, frame, text, sensitive });
  return true;
};
const COPIES = 6;
for (const [category, t] of Object.entries(facts)) {
  if (t.sensitive.length !== t.twin.length) throw new Error(`${category} 쌍 수가 다름`);
  const cred = category === 'Credential';
  t.sensitive.forEach((fact, i) => {
    for (let k = 0; k < (cred ? 3 : COPIES); k += 1) {
      for (let tries = 0; tries < 50; tries += 1) {
        const p = pick(people);
        const fi = Math.floor(rand() * frames.length);
        const s = cred ? fact.replace('{c}', pick(credValues)) : frames[fi](p, fact);
        const w = cred ? t.twin[i] : frames[fi](p, t.twin[i]);
        if (used.has(s) || (!cred && used.has(w))) continue;
        add(category, 'sensitive', '', cred ? -1 : fi, s, true);
        add('None', 'twin', category, cred ? -1 : fi, w, false);
        break;
      }
    }
  });
  // 사람 없는 주제어 문장. 판별 때는 글을 문장으로 나눠 한 문장씩 보므로 학습도 한 문장으로 둔다.
  for (const b of bare[category]) {
    add('None', 'bare', category, -1, b, false);
  }
}

// 다른 셋과 겹치지 않는지 검사: 같은 문장, 사람 표지, 사실 문장(앞 12글자).
const others = ['sentence-dev.jsonl', 'sentence-dev2.jsonl', 'sentence-dev3.jsonl', 'sentence-final.jsonl', 'shortcut-dev3.jsonl', 'sentence-train2.jsonl']
  .flatMap((f) => readFileSync(join(here, f), 'utf8').trim().split('\n').map((l) => {
    const j = JSON.parse(l);
    return j.text ?? `${j.a}\n${j.b}`;
  }));
const joined = others.join('\n');
const dev3 = ['sentence-dev3.jsonl', 'shortcut-dev3.jsonl'].flatMap((f) => readFileSync(join(here, f), 'utf8').trim().split('\n')).join('\n');
const clash = people.filter((p) => dev3.includes(p));
if (clash.length) throw new Error(`dev3 에 나온 사람 표지: ${clash.join(', ')}`);
const overlaps = [];
